        int x1, y1, x0, y0;
        x1 = (int)((prc[0] + prc[2] * 512.0f) * 0.0015625f) - 1;
        y1 = (int)((prc[1] + prc[3]) * 0.45454547f) - 1;
        x0 = (int)(prc[0] * 0.8f);
        y0 = (int)(prc[1] * 0.45454547f);
